<script lang="ts">
  import type { PageData } from './$types';
  import { createBrowserClient } from '@supabase/ssr';
  import { PUBLIC_SUPABASE_URL, PUBLIC_SUPABASE_PUBLISHABLE_KEY } from '$env/static/public';
  import { invalidateAll } from '$app/navigation';
  import { Search, AlertTriangle, CheckCircle2, Clock3 } from 'lucide-svelte';
  export let data: PageData;
  const supabase=createBrowserClient(PUBLIC_SUPABASE_URL,PUBLIC_SUPABASE_PUBLISHABLE_KEY);
  let query='', error='', message='';
  $: filtered=data.loans.filter((l)=>[l.books?.title,l.books?.author,l.borrowers?.full_name,l.borrowers?.student_id].some((v)=>(v??'').toLowerCase().includes(query.toLowerCase())));
  $: overdue=filtered.filter((l)=>l.due_date<data.today).length;
  async function markReturned(l: PageData['loans'][number]){
    if(!confirm(`Mark "${l.books?.title}" as returned?`))return;
    error='';message='';
    const {error:e}=await supabase.rpc('return_book',{p_borrowing_id:l.id});
    if(e)error=e.message;else{message='Book returned successfully.';await invalidateAll();}
  }
</script>

<div class="mb-6"><p class="text-sm font-semibold text-indigo-600">FOLLOW-UP</p><h1 class="mt-1 text-3xl font-bold tracking-tight text-slate-900">Unreturned books</h1><p class="mt-2 text-sm text-slate-500">All books that have not yet been returned, including overdue loans.</p></div>
<div class="mb-5 grid gap-4 sm:grid-cols-2"><div class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="flex items-center gap-3"><div class="grid h-10 w-10 place-items-center rounded-xl bg-amber-50 text-amber-700"><Clock3 size={20}/></div><div><div class="text-2xl font-bold text-slate-900">{data.loans.length}</div><div class="text-sm text-slate-500">Currently unreturned</div></div></div></div><div class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="flex items-center gap-3"><div class="grid h-10 w-10 place-items-center rounded-xl bg-rose-50 text-rose-700"><AlertTriangle size={20}/></div><div><div class="text-2xl font-bold text-slate-900">{data.loans.filter((l:any)=>l.due_date<data.today).length}</div><div class="text-sm text-slate-500">Overdue</div></div></div></div></div>
{#if message}<div class="mb-4 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-800">{message}</div>{/if}{#if error||data.error}<div class="mb-4 rounded-xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">{error||data.error}</div>{/if}
<div class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="flex flex-col gap-3 border-b border-slate-100 p-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 class="font-bold text-slate-900">Outstanding loans</h2><p class="mt-1 text-xs text-slate-500">{filtered.length} unreturned record(s)</p></div><div class="relative w-full sm:max-w-xs"><Search size={17} class="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input bind:value={query} placeholder="Search book or borrower..." class="w-full rounded-xl border border-slate-200 py-2.5 pl-9 pr-3 text-sm outline-none focus:border-indigo-500"/></div></div>
{#if filtered.length}<div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">Book</th><th class="px-5 py-3">Borrower</th><th class="px-5 py-3">Due date</th><th class="px-5 py-3">Status</th><th class="px-5 py-3 text-right">Action</th></tr></thead><tbody class="divide-y divide-slate-100">{#each filtered as l}<tr class="hover:bg-slate-50/70"><td class="px-5 py-4"><div class="font-semibold text-slate-800">{l.books?.title??'Unknown book'}</div><div class="mt-1 text-xs text-slate-500">{l.books?.author??''}</div></td><td class="px-5 py-4"><div class="font-medium text-slate-700">{l.borrowers?.full_name??'Unknown borrower'}</div><div class="mt-1 text-xs text-slate-500">{l.borrowers?.student_id??l.borrowers?.email??''}</div></td><td class="px-5 py-4 text-slate-600">{l.due_date}</td><td class="px-5 py-4">{#if l.due_date<data.today}<span class="rounded-full bg-rose-50 px-2.5 py-1 text-xs font-semibold text-rose-700">Overdue</span><div class="mt-1 text-xs text-rose-600">{Math.floor((new Date(data.today+'T00:00:00').getTime()-new Date(l.due_date+'T00:00:00').getTime())/86400000)} days late</div>{:else}<span class="rounded-full bg-amber-50 px-2.5 py-1 text-xs font-semibold text-amber-700">Borrowed</span>{/if}</td><td class="px-5 py-4 text-right"><button on:click={()=>markReturned(l)} class="inline-flex items-center gap-1.5 rounded-lg border border-emerald-200 px-3 py-2 text-xs font-semibold text-emerald-700 hover:bg-emerald-50"><CheckCircle2 size={15}/> Mark returned</button></td></tr>{/each}</tbody></table></div>{:else}<div class="p-12 text-center"><CheckCircle2 class="mx-auto h-10 w-10 text-emerald-500"/><h3 class="mt-3 font-semibold text-slate-800">No unreturned books</h3><p class="mt-1 text-sm text-slate-500">All loans have been returned, or no loans match your search.</p></div>{/if}</div>
